UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b129928-BCEjVaP0AQSw.png', birthday = '3月8日', blood_type = NULL, voice_actor = '坂泰斗', height = NULL, description = 'クラス：メイジ　家族：パク・ギョンヘ（母）、ソン・ジナ（姉）　ソン・ジンウは『俺だけレベルアップな件』の主人公であり、悪名高いほど弱いEランクのハンターとして知られている。 彼は謙虚で心優しい人物であり、家族を深く思いやり、より強くなりたいという強い願望を抱いている。そのため、妹や母とは親密な関係を築いており、スキルを磨き、さらなる力を得る機会をほとんど逃さない。' WHERE character_id = 'CH013694';
