UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b210102-R479fvXo78Zn.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = '「神の像」は、ダブルダンジョンの隠しボスである。Dランクダンジョン編において、ジン・ウォや他のハンターたちが、内部に潜む危険に気づかぬままカルテノン神殿に足を踏み入れた際に、初めてその存在が明らかになった。' WHERE character_id = 'CH013706';
