UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b193929-V80LPAzWwjZv.png', birthday = NULL, blood_type = NULL, voice_actor = '石川由依', height = NULL, description = NULL WHERE character_id = 'CH013779';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329981-RQgFmGfH1a8k.png', birthday = NULL, blood_type = NULL, voice_actor = '杉田智和', height = NULL, description = NULL WHERE character_id = 'CH013780';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b84769-NaLHptr4KXKd.png', birthday = NULL, blood_type = NULL, voice_actor = '市川太一', height = 168, description = '種族：人間　ランク：イレギュラー　役職：ウェーブ・コントローラー　生年月日：　職業：　第25番　バームは『タワー・オブ・ゴッド』に登場するイレギュラーであり、主要な主人公の一人である。 バムは親友のレイチェルを探して塔に入り、ヘッドンの試練を乗り越えた後、塔を登るにふさわしいと認められた。第1部において、彼は非常に共感力が高く思いやりのある若者であり、レイチェルと出会う前、そして後に塔に入るまでは人との接点がほとんどなかったため、人生についてほとんど理解していなかった。彼は孤独やその他を嫌っており、' WHERE character_id = 'CH013781';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b84781-sNnhOZ1SZ66f.png', birthday = '11月29日', blood_type = NULL, voice_actor = '岡本信彦', height = 170, description = '種族：人間　ランク：レギュラー　役職：ライトベアラー　クン・アグエロ・アグニスは、クン家出身のEランク・レギュラーであり、しばしば単に「クン」と呼ばれる。『タワー・オブ・ゴッド』の主要主人公の一人である「25番目のバム」の親友である。  クンは卓越した知性を大いに頼りにしているが、それが彼の唯一の強みというわけではない。彼は並外れた身体能力も持ち合わせており、熟練した光の担い手でもある。戦闘における彼の能力は否定できない。' WHERE character_id = 'CH013782';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135472-8gshcVPWGP2s.jpg', birthday = NULL, blood_type = NULL, voice_actor = '内田雄馬', height = NULL, description = 'ジャ・ワンナンは、塔全体の王になることを目指している。彼は、誰の願望よりも、自らの生きる決意を何よりも大切にしている。彼は、諦めてしまった者たちとは違い、塔の各階を登り続け、塔の真の頂点に到達するつもりだ。' WHERE character_id = 'CH013783';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135466-vgW4DewsSkER.jpg', birthday = NULL, blood_type = NULL, voice_actor = '早見沙織', height = NULL, description = '種族：人間　ランク：エクストラ　レイチェル（別名ミシェル・ライト）は、バームの「洞窟」を訪ねてくれた唯一の人物であり、彼にとって最良かつ唯一の友人だった。彼女は「夜」を恐れているため、タワーの頂上で待ち受ける伝説の報酬の一つである星々を、切望している。' WHERE character_id = 'CH013784';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b330238-SKxqJ8J3f77Y.jpg', birthday = NULL, blood_type = NULL, voice_actor = '松田健一郎', height = NULL, description = 'カン・ホリャンはEランクの正規兵であり、槍使いである。彼は巨体で無口な男で、右肩の上に奇妙な印が浮かんでおり、それが原因で、普段ならまるで片翼の天使のように見える。彼の上半身、そしておそらく下半身も、ボタンが付いた黒い包帯で巻かれているようだ。' WHERE character_id = 'CH013785';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135467-AyW5hucXmmea.jpg', birthday = NULL, blood_type = NULL, voice_actor = '日笠陽子', height = 168, description = '種族：レッドウィッチ　階級：一般　役職：ウェーブコントローラー、スコット、ガイド　ファリュンは口数が少なく物静かな人物で、陰鬱で不吉なオーラを漂わせている。また、かなり manipulative でもある。  パートIIでは、彼女はいたずら好きでからかい好きな一面を見せ、ヴァイオールのなりすましを露骨に嘲笑し、繰り返し「豚」と呼んでいた。彼女はほとんど常に、いたずら心と、おそらく少しの傲慢さを含んだ笑みを浮かべている。 また、他人の感情をほとんど顧みないほど極めて率直な傾向があり、この冷淡さゆえに' WHERE character_id = 'CH013786';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b168142-dpfALFB5gICI.jpg', birthday = NULL, blood_type = NULL, voice_actor = '大西沙織', height = NULL, description = 'クン・マシェニー・ジャハドは、クン家出身の「タワー」トップ100ハイランカーの一人であり、「13ヶ月シリーズ」の一つである「イエロー・メイ」の所有者です。 彼女は、クン家の中で「13ヶ月シリーズ」を授与された唯一のジャハド家のプリンセスである。彼女はクン・エダンとクン・マシェニーの直系の子孫である。' WHERE character_id = 'CH013787';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137948-NYeFyFDeIoHd.png', birthday = NULL, blood_type = NULL, voice_actor = '津田健次郎', height = NULL, description = 'レロ・ロは、かつてセカンド・フロールの試験官を務めていた人物である。彼は並外れて強いランカーであり、同じく元試験官（しかも高慢な性格の）クアントでさえ、彼の強さを絶えず自慢していたほどだ。 彼はセカンド・フロルの試験官の中で最強だったと言われており、特に「神相」の扱いに長けている。また、「光の担い手」の指導役も務めていた。彼はかなり年配で、ユリ・ザハードよりも年上である。彼自身、アナク・ザハードは王女としての「混沌とした期待」に応えられなかったと述べている。' WHERE character_id = 'CH013788';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137952-UEsMgoUb7bHQ.png', birthday = '5月2日', blood_type = NULL, voice_actor = '深町寿成', height = 167, description = '種族：人間　所属：スコット　ハツ（하츠、Hahcheu、または「ハッツ」）はレギュラーであり、「献身的に」剣術を修練する剣士である。彼は物静かで冷静な戦士であり、各試練で求められることを忠実に実行するだけで、著しい進歩を遂げている。' WHERE character_id = 'CH013789';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b353858-46HP6vqOAHJx.jpg', birthday = NULL, blood_type = NULL, voice_actor = '高橋英則', height = NULL, description = 'レフレホは、30Fワークショップ・バトルにおいて、ジュエ・ヴィオール・グレース率いるチームFUGのレギュラーメンバーであり、元漁師だった。彼はFUGの潜伏工作員として、Eランクレベルで数千年にわたり身を潜めていた。' WHERE character_id = 'CH013790';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b355034-U8eucMSc9Zce.jpg', birthday = NULL, blood_type = NULL, voice_actor = '石井瑞樹', height = NULL, description = '「トラベラー」あるいは「ミスター・トラベラー」は、正体不明のレギュラーキャラクターであり、30階での「ワークショップ・バトル」の序盤、正体不明のワークショップ・パトロールに追われている姿が初めて確認された。' WHERE character_id = 'CH013791';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383461-qMJeecGjdrjv.jpg', birthday = NULL, blood_type = NULL, voice_actor = '茅野愛衣', height = NULL, description = 'ロン・メイはFUGのレギュラーメンバーであり、30Fワークショップ・バトルイベントではチーム・マッドドッグのリーダーに任命された。彼女の役割は「ライト・ベアラー」である。彼女はマッドドッグ・ヴァラガルヴの「天使」である。' WHERE character_id = 'CH013792';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337750-m9wGFNdCXGKU.png', birthday = NULL, blood_type = NULL, voice_actor = '河西健吾', height = NULL, description = 'プリンスは、ルーカー・キャッシュ社の社長の息子である。彼は「レギュラー」であり、「ライト・ベアラー」でもある。' WHERE character_id = 'CH013793';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b189782-WG8pgL2DV6WO.jpg', birthday = NULL, blood_type = NULL, voice_actor = '堂島颯人', height = NULL, description = 'オーガスガスは、ハイランカーであり、第20フロアの試験責任者を務めている。また、FUGのメンバーでもある。' WHERE character_id = 'CH013794';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137961-Ks8VQK2vNnEy.png', birthday = NULL, blood_type = NULL, voice_actor = '笠間淳', height = NULL, description = 'ノヴィックは、ハ家の分家の一つに由来する正規兵であり、槍持ちである。' WHERE character_id = 'CH013795';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137951-PvAYnFfFoJi0.jpg', birthday = NULL, blood_type = NULL, voice_actor = '吉野裕行', height = NULL, description = 'クアント・ブリッツはランカーである。彼は第2フロアのテスト管理者だった間、スコット・ポジションの指導を担当していた。' WHERE character_id = 'CH013796';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b205162-ptEcj5j1lcK0.jpg', birthday = NULL, blood_type = NULL, voice_actor = '柿原徹也', height = NULL, description = 'クアエトロ・ブリッツはCランクのレギュラーだ。かつて28フロアの試験に一度失敗したものの、30フロアで行われたワークショップバトルには出場した。' WHERE character_id = 'CH013797';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b353859-CJClqKuGrhP4.jpg', birthday = NULL, blood_type = NULL, voice_actor = '林勇', height = NULL, description = 'エディン・ダンは、Eランクのレギュラーだった頃から驚異的なスピード能力を持つDランクのレギュラー・スコットである。彼は25階で数年間休養していたが、クン・アグエロ・アグニスに迫られ、登り続けることを余儀なくされた。' WHERE character_id = 'CH013798';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b355035-oj8TtuTnICSq.jpg', birthday = NULL, blood_type = NULL, voice_actor = '鷄冠井美智子', height = NULL, description = 'アップルは「レギュラー」タイプであり、「情報収集型」のスコットおよび「ライト・ベアラー」です。' WHERE character_id = 'CH013799';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383462-G3mwgJGVXsqU.jpg', birthday = NULL, blood_type = NULL, voice_actor = '岩井映美里', height = NULL, description = 'ノマは21階のテスト管理者で、「ジガエナの花」テストを担当していました。' WHERE character_id = 'CH013800';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b84783-m1qgQvKVAoNn.jpg', birthday = '7月7日', blood_type = NULL, voice_actor = '三宅健太', height = NULL, description = '種族：レイスレイザー、ランク：一般 Cランク、役職：槍持ち　ラク・レイスレイザーは一般兵である。セカンド・フロアでの最初の試験で、バアムやクンとは不本意ながらチームを組み、彼らと共に他の試験も突破した。 彼は「槍持ち」のポジションに選ばれた。大柄で力強い戦士であり、非常に自信に満ちた人物である。<div rel="spoiler">ラクは本来、身長3メートルの生物だったが、セカンド・フロアの試験責任者であるランカーのユ・ハンソンを嘲笑したため、その体は縮小されてしまった。' WHERE character_id = 'CH013801';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337746-3pB2Ae9V3P6a.png', birthday = NULL, blood_type = NULL, voice_actor = '嶋村侑', height = NULL, description = 'ヨ・ゴセンは「レギュラー」であり、「ライトベアラー」でもある。' WHERE character_id = 'CH013802';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b224309-3b94G7Q1b47e.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小見川千明', height = NULL, description = 'ジャイナ・レペリスタ・ザハードは、ジャイナ家のザハード家の王女である。彼女は、暗くした自室でライトホースの前に座り、タワー内で起きている出来事を眺めることに夢中になっているようだ。' WHERE character_id = 'CH013803';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135470-4glp1GObkU7P.png', birthday = NULL, blood_type = NULL, voice_actor = '関根明良', height = NULL, description = 'アナークは第2話で初登場し、そこでシビスとハッツとチームを組む。' WHERE character_id = 'CH013804';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b344561-6wOOYMkBEwOr.png', birthday = NULL, blood_type = NULL, voice_actor = '安部川賢治郎', height = NULL, description = 'ベニアミーノ・カッサーノは、「ザ・ワークショップ」が「リビング・イグニッション・ウェポン」を開発するために用いた、最初期の実験被験者の一人である。彼はDランクのレギュラーであり、スコットランド人である。かつてはチームFUGおよびチーム・レイチェルのメンバーだった。' WHERE character_id = 'CH013805';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b353860-QYXg5NwRvCc8.jpg', birthday = NULL, blood_type = NULL, voice_actor = '重松千晴', height = NULL, description = 'ベータは、ソフィア・アマエの「子供」の一人であり、ホリャンとカッサーノの「兄弟」でもある。ワークショップによって生み出された、生きたイグニッション兵器である。' WHERE character_id = 'CH013806';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383455-qyQvmG6Isfvx.jpg', birthday = NULL, blood_type = NULL, voice_actor = '松岡洋平', height = NULL, description = NULL WHERE character_id = 'CH013807';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383463-NpdgF2xQawCW.jpg', birthday = NULL, blood_type = NULL, voice_actor = '清水春那', height = NULL, description = 'ゲタンは、フロル月25日に初登場したレギュラー選手兼槍持ちだった。彼はエンドルシ・ザハードのファンであり、彼女に会えるチャンスを得るためにクンのチームに加入した。また、彼はチームの「コック」でもあったが、チームメイトのノヴィックこそがチーム随一の「コック」だったと言われている。' WHERE character_id = 'CH013808';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337747-eW3wKUZabweF.png', birthday = NULL, blood_type = NULL, voice_actor = '白石兼斗', height = NULL, description = 'ホン・アークラプターはレギュラーであり、「チーム・スウィート・アンド・ソー」のメンバーです。' WHERE character_id = 'CH013809';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b223173-TBxx0VG4Nvlo.jpg', birthday = NULL, blood_type = NULL, voice_actor = '稲垣好', height = NULL, description = 'シャ・シャは、かつて28階で情報屋として暮らしていたDランクのレギュラー兼ライトベアラーである。' WHERE character_id = 'CH013810';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141286-BCNl8KMkVQ2j.png', birthday = NULL, blood_type = NULL, voice_actor = '岸尾だいすけ', height = NULL, description = 'ユ・ハンソンはアドバンスド・ランカーであり、かつてセカンド・フロアのテストディレクターを務めていた。特に、ヴィオレを頂点へと導く上で、FUGの中心的なメンバーとして活躍した。彼はパートIの主要な敵役である。ハイ・ランカーになることを拒んだこともあって、彼はよく知られたランカーの一人となっている。' WHERE character_id = 'CH013811';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135478-hC2ZpgUpgtUS.png', birthday = NULL, blood_type = NULL, voice_actor = '小林千晃', height = NULL, description = '通称：アロフ・ウェーブ　ランク：14　ポー・ビダウ・グスタンは、ポー・ビダウ家の当主であり、「十大戦士」の一人であると同時に、シンソを体系的に記録した最初の存在でもある。 ポ・ビダウ・グスタンは、タワーで最も著名なウェーブ・コントローラーであり、作家でもある。『ワークショップ』内の風変わりな連中を除けば、彼ほどタワーについて詳しい者はいないだろう。彼は傲慢な人物として描かれており、一族内での名声と影響力は絶大で、一族の者たちでさえ、彼が全知の知性を備えていると信じ込んでいるほどである。' WHERE character_id = 'CH013812';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b353862-LDXvfYBvySq1.jpg', birthday = NULL, blood_type = NULL, voice_actor = '土師孝也', height = NULL, description = 'マドラコはハイランカーであり、グレイ・キャットフィッシュ商人組合のリーダーである。彼は優れた実業家として知られている。' WHERE character_id = 'CH013813';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383456-HzQnEvZci0xg.jpg', birthday = NULL, blood_type = NULL, voice_actor = 'いとうさとる', height = NULL, description = NULL WHERE character_id = 'CH013814';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b84777-xeZZ3a9YM2Cn.png', birthday = '3月1日', blood_type = NULL, voice_actor = '本多真梨子', height = NULL, description = 'ハ・ユリ・ジャハド（通称ユリ・ジャハド、姓は不明）は、ハ家のハイランカーであり、王女である。特に、彼女は最も有名な王女の一人であり、そのため非常に寵愛を受けており、タワー全域で大きな政治的影響力を持っている。' WHERE character_id = 'CH013815';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337749-JB6JGD2SRHsL.jpg', birthday = NULL, blood_type = NULL, voice_actor = '阿部菜摘子', height = NULL, description = 'ニャ・ニアは、20階でチャンポンの配達員として働くレギュラーキャラクターだ。その後、テストに参加するために仕事を辞める。' WHERE character_id = 'CH013816';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b124137-ZMkbYja3ty77.png', birthday = NULL, blood_type = NULL, voice_actor = '高橋広樹', height = 195, description = '種族：人間　出身地：オツサイド　ランク：イレギュラー、ハイランカー第4位（現時点）　肩書き：漁師　職業：ウォルハイクソン（副隊長）　ウレク・マジーノはイレギュラーであり、現在ハイランカー第4位にランクインしている。ジャハドが再び活動を開始するまでは、現役のランカーの中で最強の存在だった。 また、タワー内でトップ5のハイランカーに名を連ねた最新の人物でもある。 実力のないランカーたちからはファンタミヌムと同等のレベルと見なされているが、トップランカーたちの中では、彼の真の実力を測ることはほぼ不可能である。' WHERE character_id = 'CH013817';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137958-FjrhxrKil0MA.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小野大輔', height = NULL, description = 'フォンセカル・ラウローは、ユーラシア・ファミリーの正規メンバーであり、才能あふれるウェーブ・コントローラーだ。彼は寝ることが大好きで、どこへ行くにも毛布と枕を携えている。のんびり屋ではあるが、強力な長距離ビームを発射できる、卓越したウェーブ・コントローラーである。' WHERE character_id = 'CH013818';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b175702-JSnskF1Gvy3i.jpg', birthday = NULL, blood_type = NULL, voice_actor = '柳田淳一', height = NULL, description = 'アレクセイ・アミゴチャズは、第2フロル初期のレッドウィング所属のレギュラーであり、チーム・イスの一員として、シビス、アナク・ザハード、アンドロッシ・ザハードと共にタワーを登っていた。彼の役割はスピアベアラーである。' WHERE character_id = 'CH013819';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383457-Fz0kQkCsfbit.jpg', birthday = NULL, blood_type = NULL, voice_actor = '大久保藍子', height = NULL, description = NULL WHERE character_id = 'CH013820';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337745-3GUS3TyaC2uD.png', birthday = NULL, blood_type = NULL, voice_actor = '宮下早紀', height = NULL, description = 'ヨ・ミセンは、両親を探すために塔を登る「レギュラー」の一人である。' WHERE character_id = 'CH013821';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135474-2DfQO8OKNiNr.jpg', birthday = NULL, blood_type = NULL, voice_actor = '寿美菜子', height = NULL, description = 'ラン・クンは、現在タワーを登っているレギュラーの一人である。かつてはクンのチームメイトであり、ジュエ・ヴィオール・グレースのために結成されたFUGチームのメンバーでもあった。彼は、厄介な状況や人物を「うっとうしい」と表現することが多い。 ワークショップ・バトルの事件後、彼はクンの指示のもと、新たなチームを結成した。また、彼はマシェニー・ジャハドと同じクン家の分家出身である。' WHERE character_id = 'CH013822';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137957-qvngtbgmEyGT.png', birthday = NULL, blood_type = NULL, voice_actor = '江口拓也', height = NULL, description = 'シビスはDランクのレギュラーである。彼は比較的弱いが、優れた推理力とクンに匹敵する知性を備えている。それにもかかわらず、彼はセカンド・フロアのすべての試練を突破し、そこで「スコット」の役割を任され、現在はチームのリーダーとしてタワーを登り続けている。' WHERE character_id = 'CH013823';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b180904-gQLyYTTDzNCF.jpg', birthday = NULL, blood_type = NULL, voice_actor = '天月', height = NULL, description = 'ヴェスパ（ベスパー、Beseupa）は、ミツバチをモチーフにしたヒューマノイドで、シップ・チームの数名のメンバーと共にタワーを登っている。彼女は「レギュラー」であり、かなりの腕前を持つ前線戦闘員だ。ポジションは「スコット」である。成体形態に変身することができる。' WHERE character_id = 'CH013824';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b355031-718CaHbeaEl2.jpg', birthday = NULL, blood_type = NULL, voice_actor = '丸岡竜馬', height = NULL, description = 'マイケルは「レギュラー」であり、「ウェーブ・コントローラー」の一人。25階で初めて登場した。クーンのチームでは「怪しげな医者」として活動しており、「宣教師」とも呼ばれていた。クーンとレイチェルを除けば、チーム内で5番目の地位にあった。' WHERE character_id = 'CH013825';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', birthday = NULL, blood_type = NULL, voice_actor = '大木咲絵子', height = NULL, description = 'テボとレボは、実は一つの存在である二人の存在だ。彼らは「ワークショップバトル」に参加したレギュラーたちである。' WHERE character_id = 'CH013826';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b124138-2WCq8CD8FEsv.png', birthday = '12月6日', blood_type = NULL, voice_actor = '末柄里恵', height = 167, description = 'エンドルシ・ジャハドは「レギュラー」の一員であり、ジャハドの王女の一人。現在は塔を登っている。レギュラーの中でも、エンドルシの身体能力は群を抜いている。ジャハドの王女たちの中では、彼女は比較的温厚で、より人間味あふれる性格だ。  彼女が生まれた時、実の両親はそばにいなかった。その後、プリンセスになる前に、ミドルエリアの夫婦に養子として引き取られた。その後、養父母はスネーク・チャーマーに殺害された。彼女のキャラクターコンセプトは、「普通の現代の少女」であり、身だしなみを非常に気遣い、' WHERE character_id = 'CH013827';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337748-Tk7TAZOUPgoS.jpg', birthday = NULL, blood_type = NULL, voice_actor = '入江直樹', height = NULL, description = 'キム・ラーカーは、ラーカー・キャッシュに勤務する高利貸しであり、副店長を務めている。' WHERE character_id = 'CH013828';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135465-2cvQwFpNSSh7.png', birthday = NULL, blood_type = NULL, voice_actor = '沢城千春', height = NULL, description = 'カラカはFUGのスレイヤーだ。彼の秘密の隠れ家は97階にある。' WHERE character_id = 'CH013829';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b223783-A2hgdWcPxmKA.jpg', birthday = NULL, blood_type = NULL, voice_actor = '中原麻衣', height = NULL, description = 'ソフィア・アマエは、「ワークショップ」の研究助手の一人であり、ベニアミーノ・カッサーノとカン・ホリャンが12歳になるまで、言語や基本的な対人コミュニケーションを教える役割を担っていた。彼女は「ワークショップ」の「リビング・イグニッション・ウェポン」プロジェクトに携わっており、現在はエミリーと共にそのプロジェクトに注力している。' WHERE character_id = 'CH013830';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b175047-o2zQmdPwHPLu.png', birthday = NULL, blood_type = NULL, voice_actor = '内山昂輝', height = NULL, description = 'クン・ハチュリング、あるいは単にハチュリングは、ランカーであり、クン家から離反した一員であり、クン・エドゥアンと血縁関係にある多くの子供たちのうちの1人である。また、ウォルハイクソンの一員でもあり、時には「ブルーベリー」と呼ばれることもある。' WHERE character_id = 'CH013831';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b355032-PCXOwQIhBiia.jpg', birthday = NULL, blood_type = NULL, voice_actor = '熊谷健太郎', height = NULL, description = 'チャン・ブラロードはCランクの正規メンバーであり、かつてEランク正規メンバーのトップ5の一人だった漁師である。' WHERE character_id = 'CH013832';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383459-Kp0wUQM0Ki3x.jpg', birthday = NULL, blood_type = NULL, voice_actor = '杉崎亮', height = NULL, description = 'ラップデビルは、「右腕の悪魔」というあだ名を持つレギュラーで、その右腕を黒と青の縞模様の「パワーモード」に変える能力を持っている。 彼は、ある裕福な会社経営者の息子に付き添うために雇われていた。彼は、タワー内で有名な剣士でありレギュラーでもあるハッツを倒したと主張していた。' WHERE character_id = 'CH013833';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135475-XyLwecfoZB50.png', birthday = NULL, blood_type = NULL, voice_actor = '渡部紗弓', height = NULL, description = '「ヨン家の輝き」とも呼ばれるエファ・ヨンは、十大名家の一つであるヨン家の出身である。彼女はレギュラーとしてチームメイトたちと共にランクを上げており、最近ではワークショップバトルにも参加した。' WHERE character_id = 'CH013834';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b137953-pSgdxHzRDna6.png', birthday = NULL, blood_type = NULL, voice_actor = '村瀬歩', height = NULL, description = 'ミュール・ラブは、「20th Flor」のランカー兼管理者である。ミュール家に生まれ、チキン・ラブ・クラブの会員でもある。研究協会でのある試験に合格した後、ウォンスルサとなった。' WHERE character_id = 'CH013835';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135469-26GzJx3bIxnH.png', birthday = NULL, blood_type = NULL, voice_actor = '小西克幸', height = NULL, description = 'ハ・ジンソンは、ハ家のハイランカーであり、FUGのメンバーである。ジンソンは気さくで陽気な性格だが、それは彼の真意を隠すための仮面でもある。 バアムと出会って以来、彼の性格は少し穏やかになり、FUGがバアムに与えた扱いに後悔を感じるほどになった。ハ家のメンバーであり、トップ100に入るハイランカーの一人であるジンソンは、極めて強力なハイランカーであり、武術に極めて長け、並外れた身体能力を備えている。その地位は' WHERE character_id = 'CH013836';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b175717-NifIOzxcDyfF.png', birthday = NULL, blood_type = NULL, voice_actor = '相馬康一', height = NULL, description = 'パラカウルは、あまり賢くなく、役に立たないレギュラーだ。' WHERE character_id = 'CH013837';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b353857-BiDqWAmLOmmr.jpg', birthday = NULL, blood_type = NULL, voice_actor = '田島章寛', height = NULL, description = 'ヴァラガルヴは、FUG出身のスレイヤーであるベイロード・ヤマの「三匹の狂犬」の一人である。' WHERE character_id = 'CH013838';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b355033-Ro3zkjR12MYD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '立石みこ', height = NULL, description = 'ヴェルディは、シビスのチームに所属する悪名高いアニマだ。' WHERE character_id = 'CH013839';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b383460-URirUaNUjBxR.jpg', birthday = NULL, blood_type = NULL, voice_actor = '岩澤俊樹', height = NULL, description = 'デビル・ボンは、アルキメデス号で行われたワークショップ・バトルに参加したレギュラーの一人である。' WHERE character_id = 'CH013840';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146191-1kybBWWOU7nV.png', birthday = NULL, blood_type = NULL, voice_actor = '七海ひろき', height = NULL, description = '千夜は、父の神雲と共に活動する悪魔ハンターである。千夜はダンガイシュによって実験の対象とされ、体内に1000体の悪魔を埋め込まれた。' WHERE character_id = 'CH013841';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146192-HZId3lsW6q63.jpg', birthday = NULL, blood_type = NULL, voice_actor = '内田真礼', height = NULL, description = '千夜のパートナー。月湖は、千夜に深い想いを抱く、内気で控えめな少女だ。よく千夜を助けようとするが、かえってトラブルを招いてしまうことが多いと感じている。（出典：MAL）' WHERE character_id = 'CH013842';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146618-CqMELss8ag06.jpg', birthday = NULL, blood_type = NULL, voice_actor = '豊崎愛生', height = NULL, description = '千夜と月湖に付き従う水の神。水の近くにいると、姿を変えたり、力を増したりすることができる。' WHERE character_id = 'CH013843';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146952-msa1VnWPeUDg.jpg', birthday = NULL, blood_type = NULL, voice_actor = '伊藤静', height = NULL, description = 'ハナトラは京都の地を司る神である。彼女は、人を眠りに誘う花や、瞬時に蔦を生やす能力を持っている。彼女の風変わりなところの一つは、服を着ることを嫌がり、長い髪だけで体を覆い、ほとんど裸の状態で歩き回っていることだ。' WHERE character_id = 'CH013844';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b27283-8WDUspf0Fq1f.png', birthday = NULL, blood_type = NULL, voice_actor = '高田憂希', height = NULL, description = '非常に野心的で、生意気な、数百年もの歳月を生き抜いた狐のカタワラ。彼女は人間の兄であるジンカと共に、悪事を働く人間やカタワラを世から一掃し、平和と慈愛を広めるために、各地を旅している。' WHERE character_id = 'CH013845';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146283-nWRnNeINdFkJ.png', birthday = NULL, blood_type = NULL, voice_actor = '乃村健次', height = NULL, description = '神雲はダンガイシュの一員であり、「フォー・ビースト」の将軍の一人である。彼は竜に変身することができる。' WHERE character_id = 'CH013846';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b27282-RB0heJ9eID6d.png', birthday = NULL, blood_type = NULL, voice_actor = '木村良平', height = NULL, description = '真介は、ジンカとタマに出会った当時、ただの放浪の浪人だった。彼は二人の能力に魅了され、彼らについていけるよう情報を提供した。' WHERE character_id = 'CH013847';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146617-usBeStobwIpP.jpg', birthday = NULL, blood_type = NULL, voice_actor = '松岡禎丞', height = NULL, description = 'ムドは戦いが大好きなドラゴンです。' WHERE character_id = 'CH013848';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b146814-cuSFXaYeiRTG.jpg', birthday = NULL, blood_type = NULL, voice_actor = '羽多野渉', height = NULL, description = '足利義輝は、室町幕府の第13代将軍である。彼は多くの人々から称賛される名剣士である。' WHERE character_id = 'CH013849';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b220806-03hjaRo9fk2t.jpg', birthday = NULL, blood_type = NULL, voice_actor = '中島ヨシキ', height = NULL, description = 'ファルサス王国の皇太子。魔法を無効化できる伝説の王剣「アカシア」を携えている。' WHERE character_id = 'CH013850';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b220804-NPcJNFbf3fQv.jpg', birthday = NULL, blood_type = NULL, voice_actor = '種﨑敦美', height = NULL, description = '荒野にある塔の最上階に住んでおり、頂上まで登った者の願いを叶えてくれると言われている。' WHERE character_id = 'CH013851';
