UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202158-rCLSTfomAOlS.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佐藤元', height = NULL, description = NULL WHERE character_id = 'CH013864';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b331021-9CesPTMTTtye.png', birthday = NULL, blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = 'ヒメの妹。' WHERE character_id = 'CH013865';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202153-ANAiQD6UuYsD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小松未可子', height = NULL, description = 'アース・リングの王女。' WHERE character_id = 'CH013866';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202156-47ytoieis5VL.jpg', birthday = NULL, blood_type = NULL, voice_actor = '上田瞳', height = NULL, description = '現王女であり、火の指輪を宿す猫人族の中で最強の存在。' WHERE character_id = 'CH013867';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202155-XgHhUGSRQoOA.jpg', birthday = NULL, blood_type = NULL, voice_actor = '加隈亜衣', height = NULL, description = 'サフィールは、水の国マーサの双子の王女の一人である。彼女は「リング・プリンセス」としての役割を引き受け、帝国からの影響から国を救い、姉のサフィラがマルセと結ばれることができるよう、サトに「水の指輪」を託す。そして彼女はマルセの4人目の妻となる。  彼女は強力な魔法の力を持っているが、性格は怠け者だ。' WHERE character_id = 'CH013868';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b202154-gTwqtlgUow81.jpg', birthday = NULL, blood_type = NULL, voice_actor = '島袋美由利', height = NULL, description = '「風の指輪」を身に着けた、引きこもりのエルフの王女。' WHERE character_id = 'CH013869';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324330-K6d1RAvGQom4.jpg', birthday = NULL, blood_type = NULL, voice_actor = '千葉繁', height = NULL, description = 'アラバスタ、大賢者。サトとヒメからは「おじいちゃん」と呼ばれている。ヒメと「光の指輪」を守るため、彼女を連れて地球へのポータルを開くことができた。リングキング、アビス、魔法、そして世界について非常に詳しい。    若き日のある時期、スマラグディと関わりがあり、二人は愛し合っていた。彼女はエルフであるため、彼よりもはるかに長く生きる運命にあり、自分が年老いていく姿を見せることで彼女に苦痛を与えないよう、彼は去っていった。' WHERE character_id = 'CH013870';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b337783-6dcG0v0jiA3n.png', birthday = NULL, blood_type = NULL, voice_actor = '小松未可子', height = NULL, description = NULL WHERE character_id = 'CH013871';
