UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b214511-TziJiXpnAAfd.png', birthday = NULL, blood_type = NULL, voice_actor = '石田彰', height = NULL, description = NULL WHERE character_id = 'CH013873';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b214510-eAKjmsdRQXG4.png', birthday = NULL, blood_type = NULL, voice_actor = '松田颯水', height = NULL, description = NULL WHERE character_id = 'CH013874';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358431-p29Wr86sZKuc.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = '「おしり探偵」は、お尻が頭になっている探偵です。ティータイムには本を読むのが好きで、決め台詞は「うーん……事件の匂いがする」です。' WHERE character_id = 'CH013875';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358764-XjdmTSOrLENs.png', birthday = NULL, blood_type = NULL, voice_actor = NULL, height = NULL, description = 'ブラウンは「おしり探偵」の助手です。二人はよくうっかりしていて、お菓子が大好きです。' WHERE character_id = 'CH013876';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b196167-Q0C3XpQ3G6Xk.png', birthday = '8月31日', blood_type = 'AB', voice_actor = '大西沙織', height = 167, description = 'マイは学業でもスポーツでも才能に恵まれており、レナコは彼女を「美の極み」と評している。マイは学園の「マドンナ」という立場ゆえに、傲慢で率直な性格だ。普段は礼儀正しいが、レナコと二人きりになると、自分の欲望を率直に、そして執拗に訴えてくる。 彼女は気まぐれで行動する傾向がある。マイと出会った翌日、彼女はレナコに告白する。レナコは断るが、マイはしつこく迫る。二人は、マイが髪を下ろしているときは「恋人モード」であり、' WHERE character_id = 'CH013877';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b196166-rJOi9KPKHf29.png', birthday = '3月3日', blood_type = 'A', voice_actor = '中村カンナ', height = 158, description = '学校では、レナコは明るく社交的なふりをしている。しかし、クラスメートと話すことは好きだが、それはあくまで見せかけに過ぎず、彼女の「本当の自分」は陰気でネガティブだ。  中学時代、レナコはクラスメートからの遊びの誘いを断ったことで、彼らから疎外されてしまった。その結果、レナコは中学時代の残りの期間を引きこもりとして過ごした。過去の経験から、彼女はクラスメートからの誘いや頼みを断ることが苦手になっている。' WHERE character_id = 'CH013878';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b286332-UZe24xpvxBJs.png', birthday = '7月26日', blood_type = 'A', voice_actor = '市ノ瀬加那', height = 165, description = 'さつきは、率直で真面目、そして頑固な性格だ。美しい容姿とは裏腹に、冷淡な性格で、近づきがたいオーラを漂わせているため、彼女と打ち解けるのは難しい。' WHERE character_id = 'CH013879';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306048-z2ODBoBZrZfH.png', birthday = '12月12日', blood_type = 'O', voice_actor = '安齋由香里', height = 158, description = '彼女はその気さくな性格から、時々「天使」と呼ばれることもある。  セナの両親は、2人の弟、コくんときいくんの世話をするため、頻繁に家を空ける。彼女は弟たちを愛しているものの、彼らの世話をする機会が増えるにつれ、自分の自由が制限されることに不満を募らせている。' WHERE character_id = 'CH013880';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306777-0PQ8A8TM0gE6.png', birthday = '4月10日', blood_type = 'B', voice_actor = '田中貴子', height = 153, description = 'グループのマスコットであるカホは、遊び心にあふれ、陽気な性格の持ち主です。冗談を言うのが好きで、グループの雰囲気を自在に操る能力を持っています。その子供っぽい性格から、「みんなの妹」と呼ばれています。' WHERE character_id = 'CH013881';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b308290-HfnLhGbgXdb3.png', birthday = '5月28日', blood_type = NULL, voice_actor = '相良茉優', height = NULL, description = '彼女はレナコの妹だ。中学2年生で、バドミントン部の部員である。姉とは違って、生まれつき社交的で運動神経も良い。' WHERE character_id = 'CH013882';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173758-AoqioODV01ki.png', birthday = '5月1日', blood_type = NULL, voice_actor = '加藤渉', height = NULL, description = '職業：高校1年生　初登場：第1章　レンタロウは極めて親切で思いやりのある人物であり、数多くの彼女たちを心から愛しているが、その愛は時に恐ろしいほど自己犠牲的なほどである。    高校生になる前、レンタロウは計100回も振られていた。中学卒業式当日に友人から振られたことをきっかけに、彼は縁結びの神社を訪れ、神様に「高校生活が幸せになるように」と願いを捧げた。' WHERE character_id = 'CH013883';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b182333-ZDOMB50hmQ30.png', birthday = '9月3日', blood_type = NULL, voice_actor = '進藤あまね', height = NULL, description = 'タイプ：ハングリー　職業：中学3年生　初登場：第24章　ガールフレンドNo.007　くるみは食べ物が大好きで、新陳代謝が極めて高い。 そのため、彼女はほぼ常に空腹で、その瞬間に無性に食べたくなる特定の食べ物を口にしないと、ひどく不機嫌になってしまう。くるみは食べ物に関して強い連想力を持っている。ほとんど何でも食べ物を連想させてしまい、そうなるとその食べ物を食べないと、イライラしてしまって……' WHERE character_id = 'CH013884';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b254932-S5o2YF8Q7xKM.png', birthday = '8月9日', blood_type = NULL, voice_actor = NULL, height = NULL, description = 'タイプ：年配のロリ　職業：年金生活者　初登場：第75話　ガールフレンドNo.016　クスリの祖母。 ヤクは、クスリのより穏やかで大人びたバージョンのような印象を与える。他のメンバーに対しては祖母らしい振る舞いをすることが多く、家族の若いメンバーたちの若々しい騒ぎぶりを楽しんでいるようだ。また、かなり照れ屋で、レンタロウをからかう傾向がある。 また、ヤクは現代のテクノロジーにすぐ戸惑い、スマートフォンを「板」と呼んでいる。車も怖がっているようだ。ヤクは…' WHERE character_id = 'CH013885';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173759-Bu2KIzM1JELG.png', birthday = '6月22日', blood_type = 'A', voice_actor = '本渡楓', height = NULL, description = 'タイプ：デレデレ　職業：高校1年生　初登場：第1章　彼女No.001　ハカリは「不器用な計算高」な女性と評されている。彼女は目標を達成するために常に計画を練っているが、その不器用さゆえに、計画通りに進むこともあれば、そうでないこともある。 外見は上品で礼儀正しいが、内面は花園家の他のメンバーと同じくらい、あるいはそれ以上に奔放だ。また、インダ・カラネを頻繁にからかい、彼女を恥ずかしがらせたり、怒らせたりすることも多い。' WHERE character_id = 'CH013886';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173763-NShnvmT00ikJ.png', birthday = '4月18日', blood_type = NULL, voice_actor = '朝井彩加', height = NULL, description = 'タイプ：ドラッグ中毒者　職業：高校3年生、化学部部長　初登場：第10章　ガールフレンドNo.005　クスリはエネルギッシュで創意工夫に富んでおり、ほぼあらゆる用途の薬物を調合することができる。 彼女は自分が作る薬の危険性についてはあまり気にせず、しばしば嬉々として他人に無理やり飲ませたり、ためらうことなく自ら服用したりする。' WHERE character_id = 'CH013887';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b266529-zOgezCcVQAhQ.png', birthday = '10月10日', blood_type = NULL, voice_actor = NULL, height = NULL, description = 'タイプ：騎士／甘えん坊　職業：高校3年生、剣道部主将　初登場：第81話　彼女No.017　表向き、キシカは礼儀正しく、規律を重んじる人物で、話し方や振る舞いはまるで騎士そのものだ。 自分自身にも他人にも厳しい傾向があり、レンタロウ一家の中では「ツッコミ役」のような存在だ。しかし、その裏には、特にレンタロウやハハリに甘やかされ、文字通り「赤ちゃん扱い」されたいと願う、本当のキシカが隠されている。彼女がその欲望に身を任せてから……' WHERE character_id = 'CH013888';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173760-Gj3fK5VpbpT3.png', birthday = '9月9日', blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = 'タイプ：ツンデレ　職業：高校1年生　初登場：第1章　ガールフレンドNo.002　カラネは、ある状況に対する自分の感情を率直かつ正直に表現することで知られているが、2つのことについては例外だ。それは、自身の女性らしい体型（あるいはその欠如）と、相条蓮太郎への深い愛情である。 正直な性格にもかかわらず、ある状況に対する自分の気持ちを必死に隠そうとする彼女の姿は、周囲に「今にも殴りかかってきそう」という印象を与えがちだ。' WHERE character_id = 'CH013889';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b188521-rGqXf1gyqRWA.png', birthday = '5月10日', blood_type = NULL, voice_actor = '三森すずこ', height = NULL, description = 'タイプ：メイド　職業：専属メイド　初登場：第30章　ガールフレンドNo.008　花園羽々里の専属メイド。メイは礼儀正しく品行方正で、強い感情を表に出すことはめったにない。 何よりもハハリに忠誠を尽くしており、ハハリから許可を得たり、具体的に命令されたりしない限り、行動を起こすことはまずない。 メイは、レンタロウ家および花園家に対する狂信的な忠誠心から、レンタロウやハハリを脅かしたり、侮辱したり、あるいはほんの少しの迷惑さえかけたりする人物を、喜んで「排除」しようと申し出る。' WHERE character_id = 'CH013890';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b254931-SF3EaiqUx9jM.png', birthday = '4月8日', blood_type = NULL, voice_actor = '古賀葵', height = NULL, description = 'タイプ：熱血マッサージ師　職業：中学3年生　初登場：第69章　ガールフレンドNo.015　モミは少々無口で率直な性格で、それがどれほど変態的に聞こえるかを気にせず、マッサージ（特に女性へのマッサージ）が大好きだと公言している。 彼女は物に触れるのが大好きで、特に女性やキャラクターのモセパッドなど、柔らかいものを好む。モミのマッサージは極めて絶妙で、受け手は意識を失い、マッサージそのものの記憶をすべて失ってしまうほどだ。これが原因で……' WHERE character_id = 'CH013891';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173762-bmdMGoIMVz2E.png', birthday = '3月14日', blood_type = NULL, voice_actor = '瀬戸麻沙美', height = NULL, description = 'タイプ：クデレ　職業：高校1年生　初登場：第6話　ガールフレンドNo.004　ナノは実用主義が度を越しており、どんな状況でも最も効率的な方法で問題を解決することに執着している。  ナノは女の子たちの中で一番頭が良い。学力試験では満点（700/700）を取り、これは他の漫画に登場する天才レベルのキャラクターたちの得点をも上回る。ナノは円周率を数百桁まで暗記しており、時にはそれを用いて自分を落ち着かせることもある。その並外れた知性ゆえに' WHERE character_id = 'CH013892';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b190912-y0RQwDCytScP.png', birthday = '1月9日', blood_type = NULL, voice_actor = '高橋李依', height = NULL, description = 'タイプ：マゾヒスト　職業：高校1年生、野球部員　初登場：第33章　ガールフレンドNo.009　イクは野球が大好きで、部が解散の危機に瀕していた際には、部員募集のために何時間も費やすほどだ。 彼女はどんな状況でも全力を尽くすことを決意しており、その姿勢から、レンタロウからは「ストイシズムの体現者」と評されている。また、イクは極めてマゾヒスティックな性格で、痛みを楽しむために、体が耐え難いほど苦しくなるまで何時間もトレーニングを続けるほどである。' WHERE character_id = 'CH013893';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b240542-apeFs1eRNDJa.png', birthday = '8月11日', blood_type = NULL, voice_actor = '集貝はな', height = NULL, description = 'タイプ：環境に優しい巨人 職業：高校1年生 初登場：第64話 『ガールフレンドNo.014』 ヤマメは、田舎育ちのような話し方をする、とても親切で優しい少女だ。 自分の背の高さを気にしてはいるものの、その体格で他人を守れることを誇りに思っている。火の破壊力に恐怖を感じている。畑仕事をする際は、作物を踏み潰さないよう、よく竹馬を履いている。竹馬に加え、エプロンやリュックサックを身につけ、ネクタイは胸元に挟んでいる。' WHERE character_id = 'CH013894';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173761-1FcQvX74KVW7.png', birthday = '11月1日', blood_type = NULL, voice_actor = '長縄まりあ', height = NULL, description = 'タイプ：ダンデレ　職業：高校1年生　初登場：第3章　彼女No.003　静香は、特にその静かでほとんど声を出さない話し方のせいで、かなり内気で、他の人とは距離を置いているように見える。 しかし、レンタロウと出会ってからは勇気が湧いてきて、ハカリを助けるためなら自分の安全さえも犠牲にしようとするほどになった。また、レンタロウの彼女たちの中では最も謙虚で、彼が入浴している時に覗き見することを拒み、他の人たちがそうしようとするのを止めようとしたほどである。' WHERE character_id = 'CH013895';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b197921-tE2Dk71kBpH2.png', birthday = '3月3日', blood_type = NULL, voice_actor = 'Lynn', height = NULL, description = 'タイプ：ナルシスト　職業：高校2年生　初登場：第39章　ガールフレンドNo.010　ミミミはとても高慢でナルシストであり、常に自分を褒め称え、自分の美しさについて語っている。 生まれつきの美貌を持つお嬢様のような外見とは裏腹に、ミミミは実は自分の生活を支え、美しさを保つために信じられないほど努力している。お金を稼ぐために自力で働き、高価で豪華な服を買う余裕を持つために必要なところでは倹約し、さらにかなりの労力を注いでいる。' WHERE character_id = 'CH013896';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b214580-i0Z9vnHdXAf2.png', birthday = '10月1日', blood_type = NULL, voice_actor = '石原夏織', height = NULL, description = 'タイプ：コシン　職業：中学1年生　初登場：第51章　彼女No.012　千代は頼りになって几帳面な性格で、それがきっかけで学級委員長に選ばれた。 しかし、周囲から寄せられる過度な期待を密かに嫌っている。眼鏡を外すと不安になり、抑えきれないほど泣き出してしまう。' WHERE character_id = 'CH013897';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b227073-wEMvUNZpvDfi.jpg', birthday = '2月11日', blood_type = NULL, voice_actor = '竹達彩奈', height = NULL, description = 'タイプ：アメリカ人　職業： 日本語教師　初登場：第57話　ガールフレンドNo.013　ナデシコは、アメリカへの強い憧れから、自由をこよなく愛し、典型的なアメリカ人のような性格を持っている。これは、彼女の家族が守る厳格な日本の伝統的な慣習とは正反対の行動をとるアメリカの子供たちの姿が収められたVHSテープを見つけ、それを見て影響を受けたためである。 アメリカを愛しているにもかかわらず、彼女は英語を話せないようだ。' WHERE character_id = 'CH013898';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b205771-1teikIw9F5Lq.png', birthday = '10月10日', blood_type = NULL, voice_actor = '高尾奏音', height = NULL, description = 'タイプ：内気  職業：高校1年生  初登場：第45章  ガールフレンドNo.011  ミームは極度の内気な性格で、注目を集めないよう顔を隠すためにマスクを着用するほどだ。彼女はどんな状況でも顔を隠そうと努めている。 また、ミームは編み物も好きで、たくさんの小さなぬいぐるみを作っている。彼女はこれらのぬいぐるみを「目くらまし」として使い、素早く逃げ去る際に、誰にも見られないよう、気をそらすためにぬいぐるみを置いていくのだ。' WHERE character_id = 'CH013899';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173812-esAPFUOtQnKc.jpg', birthday = '5月12日', blood_type = NULL, voice_actor = '上坂すみれ', height = NULL, description = 'タイプ：MILF　職業：高校の生徒会長　初登場：第17章　ガールフレンドNo.006　ハカリの母親。ハハリは、何か可愛いものを見るまでは、とても大人びて洗練された女性として振る舞っている。 彼女は子供はもちろん、レンタロウやその家族に至るまで、可愛いものに対して抑えきれない愛情を抱いている。可愛いものを見つけると、よだれを垂らしてしまうこともある。娘と同様、彼女もレンタロウに対して変態的な面を持っており、彼に対する変態的な妄想を抱いていることが示されている。彼女は信じられないほど裕福で、' WHERE character_id = 'CH013900';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b306697-RA7Tl1oeivLt.png', birthday = NULL, blood_type = NULL, voice_actor = '千葉繁', height = NULL, description = '地元の神社の神様は、レンタロウにこう告げた。「お前の当神社への絶え間ない祈り、そして『天空の城ラピュタ』を観ている時に気が散っていたことも一因となり、高校生活の中で100人のソウルメイトに出会えるよう、お前に過剰なほどの祝福を与えてしまったのだ」と。' WHERE character_id = 'CH013901';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b36309-6KM0riV4lqfN.jpg', birthday = NULL, blood_type = NULL, voice_actor = 'うえだゆうじ', height = NULL, description = 'このキャラクターページは、それぞれの作品において具体的なビジュアルが設定されていないすべてのナレーターを紹介・一覧表示することを目的としています。具体的なビジュアルが設定されている他のナレーターキャラクターについては、このナレーターページとは別に追加してください。' WHERE character_id = 'CH013902';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b215499-ljm5hArpY0BI.png', birthday = NULL, blood_type = NULL, voice_actor = '結川あさき', height = NULL, description = '技能：逃走術：逃走、回避、隠密の複合技　紋章：三鱗　鎌倉幕府の当主となることを期待されていた北条氏の少年。 逃走に長けており、現在は諏訪大社で力を蓄え、その技能を活かして将軍の座を奪還しようと画策している。' WHERE character_id = 'CH013903';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b300904-vxt1HJTRP97E.jpg', birthday = NULL, blood_type = NULL, voice_actor = '日野まり', height = NULL, description = 'トキユキの盟友であり、「エルーシブ・ウォリアーズ」の一員。根津一族に属している。' WHERE character_id = 'CH013904';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b300902-KUbST43hFFnH.jpg', birthday = NULL, blood_type = NULL, voice_actor = '矢野妃菜喜', height = NULL, description = '頼重の配下にある諏訪神社の巫女。「エルーシブ・ウォリアーズ」の一員である。' WHERE character_id = 'CH013905';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b300905-2rFbvRj3x19v.png', birthday = NULL, blood_type = NULL, voice_actor = '鈴代紗弓', height = NULL, description = '「エルーシブ・ウォリアーズ」のメンバー。' WHERE character_id = 'CH013906';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b300906-d5uZg3GHCLXM.png', birthday = NULL, blood_type = NULL, voice_actor = '悠木碧', height = NULL, description = '諏訪一族の分家である風間一族に属する盗賊。「幻の戦士たち」の一員である。' WHERE character_id = 'CH013907';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b320996-Y6gjkjSOZzyF.png', birthday = NULL, blood_type = NULL, voice_actor = '戸谷菊之介', height = NULL, description = '主君を求めて旅を続ける戦略家であり剣士。元々は「エルーシブ・ウォリアーズ」の一員だった。' WHERE character_id = 'CH013908';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b300898-srI6TPvY23SO.jpg', birthday = NULL, blood_type = NULL, voice_actor = '中村悠一', height = NULL, description = '能力：未来視　諏訪明神の霊を宿していることから、諏訪の神として崇められている。1333年に一族が滅亡した後、時行に安身を与えた人物である。日本における最も傑出した3人の荒人神の一人である。' WHERE character_id = 'CH013909';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b300903-JlhStFm101hf.jpg', birthday = NULL, blood_type = NULL, voice_actor = '小西克幸', height = NULL, description = 'その圧倒的な力とカリスマ性で鎌倉幕府を打倒し、時行の家族と地位を失わせた男。' WHERE character_id = 'CH013910';
